actions.script:
_createOrg = _createScope.activeOrgId
productName = (productName ?: '').toString().trim()
printName = (printName ?: '').toString().trim()
pseudoId = (pseudoId ?: '').toString().trim()
productTypeEnumId = productTypeEnumId ?: 'PtAsset'
_createError = null
if (!_createOrg) _createError = 'Select an organization before creating a product.'
else if (!productName) _createError = 'Product Name is required.'
else if (!uqcEnumId) _createError = 'Unit is required.'
else if (!(uqcEnumId in ['NOS','KGS','MTR','PCS','LTR'])) _createError = 'Choose a valid unit.'
else if (productName.length()>255 || printName.length()>255) _createError = 'Product and print names can contain at most 255 characters.'
else if (pseudoId.length()>100) _createError = 'Item Code can contain at most 100 characters.'
else if (description?.size()>500 || hsnSacCode?.size()>20) _createError = 'Description or tax code is too long.'
else if (!(productTypeEnumId in ['PtAsset','PtService','PtDigitalAsset'])) _createError = 'Choose a valid product type.'
else if (enableBatchTracking && !(enableBatchTracking in ['Y','N'])) _createError = 'Choose Yes or No for batch tracking.'
else if (isGstExempt && !(isGstExempt in ['Y','N'])) _createError = 'Choose a valid tax-free option.'
else if (gstSlabId && !ec.entity.find('zenith.erp.india.IndiaGstSlab').condition('gstSlabId',gstSlabId).one()) _createError = 'Choose an existing GST rate.'
if (!_createError && productCategoryId) {
    def category = ec.entity.find('mantle.product.category.ProductCategory')
        .condition('productCategoryId', productCategoryId).disableAuthz().one()
    if (!category || category.ownerPartyId != _createOrg)
        _createError = 'Choose a category from your active organization.'
}
[mrpAmount:'MRP',reorderPoint:'Stock Alert',openingStock:'Opening Stock'].each { key, label ->
    if (_createError) return
    def raw = context.get(key)
    try {
        def input = raw == null ? '' : raw.toString().trim()
        def pattern = key=='mrpAmount' ? /[0-9]{1,12}(?:\.[0-9]{1,2})?/ : /[0-9]{1,12}(?:\.[0-9]{1,6})?/
        if (input && !(input ==~ pattern)) throw new IllegalArgumentException()
        context.put(key,input ? new BigDecimal(input) : null)
    } catch (Exception ignored) {
        _createError = label+' must be zero or a positive number.'
    }
}

def conflict = ec.service.sync().name('zenith.barcode.BarcodeServices.check#ProductCodeConflict')
    .parameters([organizationPartyId:_createOrg,code:pseudoId]).disableAuthz().call().conflict
if (conflict) {
    ec.message.addError("The code '${pseudoId}' is already used in this organization. Each current item needs a unique scan code.")
}

if (!createOut?.productId) return
if (!pseudoId) {
    pseudoId = 'ZC-'+createOut.productId
    // Account for imported codes that may already have used our preferred generated value.
    while (ec.service.sync().name('zenith.barcode.BarcodeServices.check#ProductCodeConflict')
            .parameters([organizationPartyId:_createOrg,code:pseudoId,productId:createOut.productId])
            .disableAuthz().call().conflict) {
        pseudoId = 'ZC-'+java.util.UUID.randomUUID().toString().replace('-','').take(12).toUpperCase(java.util.Locale.ROOT)
    }
}

context.catalogExport = ec.web?.parameters?.renderMode == 'csv'
context.catalogIncludeFilters = !catalogExport
ec.resource.script('component://zenith-erp-inventory/script/ProductCatalog.groovy', null)
if (catalogReadError) throw new org.moqui.context.ArtifactAuthorizationException(catalogReadError)
if (catalogExport) {
    ec.web.response.setHeader('Cache-Control', 'no-store')
    context.productList = catalogData.rows
}
def currency = companyCurrency ?: ec.entity.find('zenith.erp.base.CompanySettings')
    .condition('organizationPartyId', catalogOrgId).condition('settingKey', 'CURRENCY_UOM_ID')
    .disableAuthz().one()?.settingValue ?: 'INR'
catalogCurrencySymbol = [INR:'₹',USD:'$',GBP:'£',AED:'AED',EUR:'€',JPY:'¥'][currency] ?: currency
